@Translatable.Name(value="Inventory Access Starts Locked")
@Translatable.Desc(value="Gate cheek-pouch storage behind gourmet cuisine, because drama.")
public boolean requireFoodMixToUnlockCheeks = true;
@Translatable.Name(value="Use 'Hampter' as Default Name")
@Translatable.Desc(value="Changes the default entity name from 'Hamster' to 'Hampter'. Note: This has no visible effect in vanilla Minecraft, as mobs don't show nameplates by default. It's primarily for use with mods like Jade or Auto Leveling that display entity names.")
public boolean useHampterName = false;
@Translatable.Name(value="Enable Petting")
@Translatable.Desc(value="If true, looking affectionately at your hamster might result in spontaneous petting. Also enables the Pet Hamster keybind.")
public boolean enablePetting = true;
@Translatable.Name(value="Enable GUI Renaming")
@Translatable.Desc(value="Lets you rename hamsters directly from their inventory screen. Much more civilized than slapping them with a name tag.")
public boolean enableGuiRenaming = true;
@Translatable.Name(value="Allow Taming to Re-Enable AI")
@Translatable.Desc(value="If true, players can tame frozen, AI-disabled hamsters, instantly breathing life into them like some sort of furry necromancer. Turn this off if you're using command-spawned hamsters as statues or shop displays and don't want your patrons walking off with the merchandise happily following.")
public boolean allowTamingAiDisabled = true;
@Translatable.Name(value="Prevent Owner Friendly Fire")
@Translatable.Desc(value="If true, your weapons will magically pass through your own tamed hamsters. Perfect for those with butter fingers who keep 'accidentally' sending their companions to the great hamster wheel in the sky.")
public boolean preventOwnerFriendlyFire = false;
@Translatable.Name(value="Mob Interactions")
@Translatable.Desc(value="Configure how hamsters interact with (or terrify) other creatures.")
public ConfigGroup mobInteractions = new ConfigGroup("mobInteractions", true);
@Translatable.Name(value="Frighten Ravagers")
@Translatable.Desc(value="Should Ravagers, the hulking beasts of destruction, flee in terror from a tiny ball of fluff? Yes. Yes, they should.")
public boolean enableRavagerFlee = true;
@ConfigGroup.Pop.Container(value={@ConfigGroup.Pop, @ConfigGroup.Pop})
@Translatable.Name(value="Frighten Spiders")
@Translatable.Desc(value="Turns your hamster into a mobile arachnid-repellent unit. Highly effective.")
