import net.minecraft.client.Minecraft;
import net.minecraft.network.chat.Component;
import net.minecraft.resources.ResourceLocation;
import org.jetbrains.annotations.NotNull;

@Translatable.Name(value="General Settings")
@Translatable.Desc(value="The command center for rodent-based chaos. Tweak physics, nerf cheese, and generally play god with small furry creatures.")
public class AhpMainConfig
extends Config {
    @Translatable.Name(value="Core Feature Toggles")
    @Translatable.Desc(value="Fundamental hamster hijinks\u2014 fiddle at your own risk.")
    public ConfigGroup core = new ConfigGroup("core", true);
    @Translatable.Name(value="Enable Redstone Fever")
    @Translatable.Desc(value="Controls whether Redstone Fever can appear. Turning this off also cures every infected hamster.")
    public boolean enableRedstoneFever = true;
    @Translatable.Name(value="Enable Breeding")
    @Translatable.Desc(value="Whether hamsters are allowed to multiply. Turn this off if you fear someone on your server plans to create a rodent horde.")
    public boolean enableBreeding = true;
    @Translatable.Name(value="Enable Teleport Rescue")
    @Translatable.Desc(value="If true, hamsters that are actively following you (not sitting or wandering) will instantly teleport with you, across dimensions and even if their current chunk becomes unloaded. WARNING: do not turn this off unless you want to risk your hamsters being left behind on long teleports.")
    public boolean enableTeleportRescue = true;
    @Translatable.Name(value="Prevent End Portal Travel")
    @Translatable.Desc(value="If true, hamsters that wander into the exit End Portal will bounce right back out instead of teleporting to the Overworld and getting lost. (Make sure 'Enable Teleport Rescue' is on so they can come with you when you go through).")
    public boolean preventHamsterEndPortalTravel = true;
    @Translatable.Name(value="Enable Hamster Throwing")
    @Translatable.Desc(value="Do we yeet the hamster? ('G' by default).")
    public boolean enableHamsterThrowing = true;
    @Translatable.Name(value="Enable Wander Mode")
    @Translatable.Desc(value="For when you need some personal space. Allows tamed hamsters to be linked to a Hamster Bed, letting them wander freely within a set radius instead of clinging to you like melted duct-tape. You're welcome.")
    public ValidatedBoolean enableWanderMode = new ValidatedBoolean(true);
    @Translatable.Name(value="Enable Crop Snacking")
    @Translatable.Desc(value="Whether wandering hamsters are allowed to snack on nearby crops. If enabled, they will occasionally pillage your fully grown crops, accidentally replant seeds, and stuff the profits into their face.")
    public boolean enableCropSnacking = true;
    @Translatable.Name(value="Enable Stealing/Fetching")
    @Translatable.Desc(value="Permits hamsters to engage in spontaneous, high-stakes games of keep-away with your valuables.")
    public boolean enableItemStealing = true;
    @Translatable.Name(value="Enable Hamster-vs-Player Tag")
    @Translatable.Desc(value="Allow hamsters to give in to their playful urges and help you recover from your chronic stoicism.")
    public boolean enableTagGame = true;
    @Translatable.Name(value="Enable Hamster-vs-Hamster Tag")
    @Translatable.Desc(value="Allow hamsters to start a game of tag with each other.")
    public boolean enableInterHamsterTag = true;
    @Translatable.Name(value="Enable Hide & Seek")
    @Translatable.Desc(value="Allow hamsters to spontaneously hide in bushes or containers.")
    public boolean enableHideAndS

